using System;using System.IO;using System.Linq;using Conan.PluginApi;
class CloudMarketTests {
 [STAThread]static int Main(string[] args){string root=args[0];Directory.CreateDirectory(root);try{string index=Path.Combine(root,"index.json");PluginManager.Download("https://raw.githubusercontent.com/zrqworkmail-cloud/conan-desktop-plugins/refs/heads/main/catalog.json?refresh="+DateTime.UtcNow.Ticks,index);var entries=PluginCatalog.ParseRemote(File.ReadAllText(index));if(entries.Length!=3)throw new Exception("unexpected catalog size");Console.WriteLine("PASS cloud catalog: "+String.Join(", ",entries.Select(e=>e.Id)));using(var manager=new PluginManager(Path.Combine(root,"profile"))){manager.Install(args[1]);manager.SetEnabled("system-monitor",true);var original=manager.Service<ITelemetryBackend>("system-monitor");if(original==null)throw new Exception("bundled monitor unavailable");var originalType=original.GetType();string originalHash=PluginManager.Inspect(args[1]).Files["lib/Conan.SystemMonitor.dll"];manager.SetEnabled("system-monitor",false);manager.Uninstall("system-monitor");Console.WriteLine("PASS bundled monitor loaded and removed before cloud reinstall");foreach(var entry in entries){string package=Path.Combine(root,entry.Id+".conanplugin");long transferred=-1;long? advertised=null;PluginManager.Download(entry.Package,package,(bytes,total)=>{transferred=bytes;advertised=total;});if(transferred!=new FileInfo(package).Length||(advertised.HasValue&&advertised.Value!=transferred))throw new Exception("download progress incorrect");Console.WriteLine("PASS real cloud download progress: "+entry.Id);PluginCatalog.VerifyDownloaded(entry,package);manager.Install(package);if(manager.Enabled(entry.Id))throw new Exception("installation unexpectedly enabled plugin");manager.SetEnabled(entry.Id,true);if(entry.Id=="file-search"){var service=manager.Service<IFileSearchBackend>(entry.Id);var fixture=Path.Combine(root,"fixture");Directory.CreateDirectory(fixture);File.WriteAllText(Path.Combine(fixture,"clue.txt"),"x");if(service==null||service.Search(fixture,"clue",System.Threading.CancellationToken.None).Files.Count!=1)throw new Exception("search unavailable");}else if(entry.Id=="text-tools"){var tools=manager.Service<ITextToolsBackend>(entry.Id);if(tools==null||tools.Process("unique","a\nb\na")!="a"+Environment.NewLine+"b")throw new Exception("text plugin unavailable");}else if(entry.Id=="system-monitor"){var reloaded=manager.Service<ITelemetryBackend>(entry.Id);if(reloaded==null)throw new Exception("monitor unavailable");string newHash=PluginManager.Inspect(package).Files["lib/Conan.SystemMonitor.dll"];if(originalHash!=newHash&&Object.ReferenceEquals(originalType,reloaded.GetType()))throw new Exception("old assembly remained active after reinstall");Console.WriteLine("PASS new monitor assembly loaded after reinstall");}manager.SetEnabled(entry.Id,false);manager.Uninstall(entry.Id);Console.WriteLine("PASS cloud download, hash, install, enable, disable and uninstall: "+entry.Id);}}return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
